/* Original mobile layout; navigation patterns inspired by Ionic and Konsta UI. */
const mobilePreviousNav=hubNav;
hubNav=function(){let html=mobilePreviousNav();html=html.replace('</header>','<button class="mobile-menu-toggle" data-mobile-menu aria-expanded="false" aria-label="打开工具菜单">☰</button></header>');return html+`<nav class="mobile-tabs" aria-label="手机主导航"><button data-hub="home" ${view==='hub'?'aria-current="page"':''}><span aria-hidden="true">⌂</span>学习</button><button data-hub="books" ${view==='books'||view==='reader'?'aria-current="page"':''}><span aria-hidden="true">▤</span>书房</button><button data-account="open" ${view==='account'?'aria-current="page"':''}><span aria-hidden="true">○</span>我的</button><button data-mobile-menu aria-expanded="false"><span aria-hidden="true">☰</span>工具</button></nav>`;};
document.addEventListener('click',e=>{const toggle=e.target.closest('[data-mobile-menu]');if(toggle){const header=document.querySelector('.hub-header');const open=header.classList.toggle('mobile-menu-open');document.querySelectorAll('[data-mobile-menu]').forEach(b=>b.setAttribute('aria-expanded',String(open)));return;}if(e.target.closest('.hub-header nav button'))document.querySelector('.hub-header')?.classList.remove('mobile-menu-open');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('.hub-header')?.classList.remove('mobile-menu-open');document.querySelectorAll('[data-mobile-menu]').forEach(b=>b.setAttribute('aria-expanded','false'));}});
const mobilePreviousRender=render;render=function(){mobilePreviousRender();document.body.dataset.mobileView=view;const bar=document.querySelector('#app > .subject-bar');if(bar&&!document.querySelector('.classroom-switcher')){const wrapper=document.createElement('details');wrapper.className='classroom-switcher mobile-subject-picker';const summary=document.createElement('summary');summary.textContent='切换课堂';bar.replaceWith(wrapper);wrapper.append(summary,bar);}if(view==='account')document.querySelector('.classroom-switcher')?.setAttribute('hidden','');};
render();
